// GENERATED by packages/mcp/scripts/build.mjs from src/lib/closures.mjs. Do not edit here.
// Which I-5 rest areas Caltrans reports closed right now. One pure module for
// the drive on the I-5 guide (src/components/RouteLine.astro runs it in the
// browser) and for the MCP tools (vendored to packages/mcp by
// packages/mcp/scripts/build.mjs, so it must import nothing).
//
// Data rule: a closure comes only from the Caltrans lane-closure feed the
// conditions loop reads (worker/conditions-core.mjs, document
// /api/v1/conditions/i-5.json). Nothing here infers one: it only decides
// which published closure belongs to which rest-area stop, and shows
// Caltrans' own reason and end time as published.
//
// Matching (docs/DECISIONS.md, 110). A stop is { s, dir }: its meters on the
// I-5 axis and the direction it serves ("northbound" or "southbound"; a stop
// with no direction is never matched). A closure counts when it is
//   - active: type Full (all lanes), started, and not past its end time
//     (an open end, indefinite, stays active),
//   - in the stop's direction,
//   - within CLOSURE_TOLERANCE_M of the stop on the axis (its [sBegin, sEnd]
//     span, so a long closure covers a stop inside it), and
//   - a closure of the rest area itself (facility "Rest Area") or of the ramp
//     that leads to it (facility "Off Ramp": a rest area is entered only by
//     its own off-ramp, so a full closure of that ramp at the rest area's
//     mile closes it to the driver; Tejon Pass northbound is published this
//     way). A rest area's closure outranks a ramp's.
// Lane, shoulder, moving and on-ramp closures never close a rest area.

export const CLOSURE_TOLERANCE_M = 400;
/** A conditions document older than this is not used (the loop rebuilds it every 15 minutes). */
export const CONDITIONS_STALE_MS = 2 * 60 * 60_000;

const lower = (x) => String(x ?? "").toLowerCase();

/**
 * The closures of a conditions document that can be used now, or null when
 * the document is missing, malformed or older than two hours.
 * { closures, fetchedAt }
 */
export function usableClosures(doc, now = Date.now()) {
  if (!doc || typeof doc !== "object" || !Array.isArray(doc.closures))
    return null;
  const at = Date.parse(doc.fetchedAt);
  if (!Number.isFinite(at)) return null;
  // A reading from the future is a broken clock, not news.
  if (now - at > CONDITIONS_STALE_MS || at - now > 10 * 60_000) return null;
  const closures = doc.closures.filter(
    (c) =>
      c &&
      typeof c === "object" &&
      Number.isFinite(Number(c.sBegin)) &&
      Number.isFinite(Number(c.sEnd)) &&
      typeof c.direction === "string",
  );
  return { closures, fetchedAt: doc.fetchedAt };
}

/** True when the closure is a full closure in effect at `now`. */
export function isActiveFull(c, now = Date.now()) {
  if (lower(c.type) !== "full") return false;
  const sec = now / 1000;
  const start = Number(c.startEpoch);
  if (Number.isFinite(start) && c.startEpoch != null && start > sec)
    return false;
  if (c.endEpoch != null && Number.isFinite(Number(c.endEpoch)))
    return Number(c.endEpoch) > sec;
  return true; // no end published (indefinite)
}

/** Meters from s to the closure's span on the axis (0 inside it). */
const gap = (c, s) => {
  const lo = Math.min(Number(c.sBegin), Number(c.sEnd));
  const hi = Math.max(Number(c.sBegin), Number(c.sEnd));
  return Math.max(0, lo - s, s - hi);
};

/**
 * The closure that closes this stop, as the answer shows it, or null.
 * `usable` is the result of usableClosures().
 * { reason, until, source: "Caltrans", fetched_at, facility, direction, id }
 * `until` is an ISO time, or null when Caltrans publishes no end.
 */
export function closureFor(stop, usable, now = Date.now()) {
  if (!stop || !usable || !Number.isFinite(Number(stop.s))) return null;
  const dir = lower(stop.dir);
  if (dir !== "northbound" && dir !== "southbound") return null;
  let best = null;
  for (const c of usable.closures) {
    if (lower(c.direction) !== dir || !isActiveFull(c, now)) continue;
    const facility = lower(c.facility);
    const kind =
      facility === "rest area" ? 0 : facility === "off ramp" ? 1 : null;
    if (kind === null) continue;
    const d = gap(c, Number(stop.s));
    if (d > CLOSURE_TOLERANCE_M) continue;
    const rank = kind * 1e6 + d;
    if (!best || rank < best.rank) best = { rank, c };
  }
  if (!best) return null;
  const c = best.c;
  return {
    reason: String(c.work ?? "").trim() || "no reason published",
    until: isoFromEpoch(c.endEpoch),
    source: "Caltrans",
    fetched_at: usable.fetchedAt,
    facility: c.facility,
    direction: c.direction,
    id: c.id ?? null,
  };
}

/**
 * An ISO time from a feed's epoch seconds; null when there is none, or when the number is
 * no real date (a garbage or wrong-unit epoch, past what a Date can hold), so the answer
 * reads "end not set" instead of throwing.
 */
export function isoFromEpoch(sec) {
  if (sec == null || sec === "") return null;
  const d = new Date(Number(sec) * 1000);
  return Number.isFinite(d.getTime()) ? d.toISOString() : null;
}

/** "Apr 21, 2027", in California time, from an ISO time. */
export function closureDate(iso) {
  return new Date(iso).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "America/Los_Angeles",
  });
}

/** The plain line: "Closed now: Rest Area Maintenance, until Apr 21, 2027 (Caltrans)". */
export function closureLine(closed) {
  return `Closed now: ${closed.reason}, ${closed.until ? `until ${closureDate(closed.until)}` : "end not set"} (${closed.source ?? "Caltrans"})`;
}
